import {formatDistanceMeters} from './display-format.js';
import {escapeHTML as esc,icon} from './icons.js';
import {areaCoordinates} from './candidate-overview.js';

const number=(value,digits=1)=>Number.isFinite(value)?value.toLocaleString('en-US',{maximumFractionDigits:digits,minimumFractionDigits:digits}):'Unavailable';
const safeURL=url=>typeof url==='string'&&/^https:\/\//.test(url)?url:null;
export function comparisonTakeaway(result){
 if(!result.scoreEligible)return 'This Earth area needs a coverage review. Its terrain index is withheld.';
 const a=result.earthStats,b=result.targetStats,relief=a.relief-b.relief,slope=a.slopeMean-b.slopeMean;
 const heightText=Math.abs(relief)<1?'less than 1 m difference in elevation range':`${number(Math.abs(relief),0)} m ${relief<0?'less':'more'} elevation range`;
 const slopeText=Math.abs(slope)<.01?'less than 0.01° difference in mean slope':`a ${number(Math.abs(slope),2)}° ${slope<0?'gentler':'steeper'} mean slope`;
 return `Earth has ${heightText} and ${slopeText} compared with the planetary area.`;
}
function measurement(title,helper,a,b,unit,planet){
 const max=Math.max(a,b,1),digits=unit==='°'?2:0;
 return `<article class="panel evidence-measure"><h2>${title}</h2><p>${helper}</p>${[['Earth',a,'earth'],[planet,b,'planet']].map(([label,value,key])=>`<div class="evidence-bar-row"><span>${esc(label)}</span><div class="evidence-bar ${key}"><i style="width:${Math.max(0,value/max*100)}%"></i></div><strong>${number(value,digits)}${unit}</strong></div>`).join('')}</article>`;
}
export function comparisonIntroHTML({target,candidate,result,spacing,thumbnail,targetData,candidateData}){
 const a=result.earthStats,b=result.targetStats;
 const previewScale=site=>{const data=site===candidate?candidateData:targetData;return data?formatDistanceMeters(data.widthMeters)+' × '+formatDistanceMeters(data.depthMeters)+' · '+formatDistanceMeters(data.widthMeters/(data.size-1))+' sampling grid':'32 km study area';};
 const photos=[[candidate,'EARTH','earth'],[target,target.country.toUpperCase(),'planet']].map(([site,tag,key])=>`<article class="panel evidence-area ${key}"><div class="evidence-area-heading"><span class="evidence-body-tag">${esc(tag)}</span><div><h2>${esc(site.name)}</h2><p>${esc(site.country)} · ${areaCoordinates(site)}</p></div></div><figure><img class="terrain-preview-image" src="${esc(thumbnail(site))}" alt="Full elevation-derived terrain map for ${esc(site.name)}"><figcaption><strong>Elevation map · shaded relief</strong><span>${esc(previewScale(site))} · Regional data; fine features unresolved</span></figcaption></figure></article>`).join('<span class="evidence-pair-arrow" aria-hidden="true">↔</span>');
 const gentle=s=>(s.slopeHistogram[0]+s.slopeHistogram[1])*100;
 return `<div class="evidence-pair-heading"><span>${esc(candidate.origin?'Search-selected Earth area':'Reference Earth area')} ↔ ${esc(target.country)}</span><button class="text-link" id="change-comparison-pair">Choose another pair ↓</button></div><div class="evidence-area-grid">${photos}</div><p class="terrain-preview-note">Full study areas · Colors are scaled within each map; contour lines interpolate the same data grid. Compare terrain using the measurements below.</p>
 <section class="panel evidence-takeaway" aria-label="Main terrain finding">${icon('terrain')}<h2>Main terrain finding</h2><p>${esc(comparisonTakeaway(result))}</p></section>
 <div class="evidence-measure-grid">${measurement('How steep is the terrain?','Mean regional slope',a.slopeMean,b.slopeMean,'°',target.country)}${measurement('How much does the height vary?','Highest point minus lowest point',a.relief,b.relief,' m',target.country)}</div>
 <div class="evidence-scale-row"><p class="panel evidence-scale">Same analysis scale · 32 km areas · ${spacing/1000} km grid <button class="text-link" id="comparison-method-summary">How matching works ↗</button></p><div class="panel evidence-index"><strong>Terrain index ${result.scoreEligible?number(result.score)+' / 100':'withheld'}</strong><span>${result.scoreEligible?'Heuristic score · not a probability':'Coverage review required'}</span></div></div>
 <div class="evidence-findings"><article class="panel"><h3>What is similar?</h3><p>${result.scoreEligible?`Ground below 5° slope: ${number(gentle(a))}% Earth / ${number(gentle(b))}% ${esc(target.country)}.`:'Full-window measurements remain available. Inland terrain similarity is not scored.'}</p></article><article class="panel"><h3>What is different?</h3><p>Elevation range differs by ${number(Math.abs(a.relief-b.relief),0)} m. Mean slope differs by ${number(Math.abs(a.slopeMean-b.slopeMean),2)}°.</p></article><article class="panel"><h3>What could teams study? <span class="proposed-use">Proposed use</span></h3><p>${result.scoreEligible?'Practise regional map reading and plan observation stops across the measured terrain.':'Review coverage and obtain finer land/water evidence before proposing terrain exercises.'}</p></article></div>
 <p class="evidence-visible-limit">The index uses full slope distributions and elevation range. Regional terrain only; source accuracy varies. Geology, field access and mission suitability need further assessment. Previous analog research needs review unless citations are provided.</p>`;
}
export function comparisonEmptyHTML(){return `<section class="panel evidence-empty"><div>${icon('compare')}<h2>Choose two places to compare</h2><p>Run Automatic Search in Explore, then select a location pair. Its measurements and source records will appear here.</p><div class="evidence-empty-actions"><button class="button button-primary" id="compare-start-search">Find matching locations</button><button class="button button-outline" id="compare-use-manual">Choose a manual comparison</button></div><p class="source-note">Previously loaded areas remain available through manual comparison.</p></div></section>`;}

export function sourceDescriptor(site,data,spacing){
 const source=data.source||{},original=source.originalSource||source;
 const provider=source.id==='mola'?'NASA MOLA':source.id==='lola'?'NASA LOLA':['terrarium','srtm','skadi'].includes(source.id)?'Mapzen / Tilezen':source.title||'Source record';
 const native=source.nativeResolutionMetersApprox||source.nativePixelSpacingMetersAtCenter;
 return{body:site.country,name:site.name,provider,title:source.title||'Elevation source',nativePosting:Number.isFinite(native)?'About '+number(native,0)+' m':'Varies by source; inspect original record',analysisSpacing:number(spacing,0)+' m',originalURL:safeURL(original.url)||safeURL(source.url),labelURL:safeURL(original.labelUrl)||safeURL(source.labelUrl),observationStart:original.observationStart||null,observationStop:original.observationStop||null,caveat:source.id==='mola'||source.id==='lola'?'Gridded elevation can interpolate between instrument tracks.':'Mixed-source terrain; underlying accuracy and vertical datum vary by location.'};
}
export function selectedSourceCardsHTML({target,candidate,targetData,candidateData,spacing}){
 return `<div class="evidence-source-grid">${[[candidate,candidateData],[target,targetData]].map(([site,data])=>{const s=sourceDescriptor(site,data,spacing);return `<article class="panel evidence-source-card"><div class="evidence-source-title">${icon('source')}<div><p class="eyebrow">${site.body==='earth'?'EARTH':esc(site.country.toUpperCase())}</p><h2>${site.body==='earth'?'Earth':esc(site.country)} elevation</h2><h3>${esc(s.provider)}</h3><p>${esc(s.title)}</p></div></div><dl><div><dt>Used for</dt><dd>Terrain shape and slope</dd></div><div><dt>Coverage</dt><dd>32 km area · ${esc(site.name)}</dd></div><div><dt>Source posting</dt><dd>${esc(s.nativePosting)}</dd></div><div><dt>Analysis grid</dt><dd>${esc(s.analysisSpacing)}</dd></div>${s.observationStart?`<div><dt>Observations</dt><dd>${esc(s.observationStart.slice(0,10))} – ${esc((s.observationStop||'').slice(0,10))}</dd></div>`:''}</dl><p class="evidence-source-caveat">${esc(s.caveat)} Posting is not measurement accuracy.</p>${s.originalURL?`<a href="${esc(s.originalURL)}" target="_blank" rel="noopener noreferrer">Open original dataset ↗</a>`:'<p>Original URL unavailable; inspect the recorded provenance.</p>'}${s.labelURL?`<a class="source-label-link" href="${esc(s.labelURL)}" target="_blank" rel="noopener noreferrer">Source label ↗</a>`:''}</article>`;}).join('')}</div>`;
}
export function comparisonStepsHTML(){return `<section class="evidence-steps"><h2>How the comparison works</h2><div>${[['Read real elevation data','Take equal-sized study areas.'],['Use the same scale','Compare slope patterns and height range.'],['Calculate terrain similarity','Explain the measured similarities and differences.']].map(([title,text],i)=>`<article class="panel"><span>${i+1}</span><div><h3>${title}</h3><p>${text}</p></div></article>`).join('')}</div></section><section class="panel evidence-meaning"><h2>What this result means</h2><div><p>A candidate terrain analog for further study.</p><p>The index is not a probability or mission approval.</p><p>Review previous analog research using the available citations.</p></div></section>`;}
